public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || paths == null || start.length != 2 || end.length != 2 || paths.length != n * n - 1) {
        return "invalid input";
    }

    int[][] maze = new int[n][n];
    for (int[] path : paths) {
        maze[path[0]][path[1]] = 1;
    }

    if (maze[start[0]][start[1]] == 1 || maze[end[0]][end[1]] == 1) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);
    visited[start[0]][start[1]] = true;

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int x = current[0];
        int y = current[1];
        if (x == end[0] && y == end[1]) {
            return "can be travelled";
        }

        for (int[] direction : new int[][]{{0, 1}, {1, 0}, {-1, 0}, {0, -1}}) {
            int newX = x + direction[0];
            int newY = y + direction[1];
            if (newX < 0 || newX >= n || newY < 0 || newY >= n || visited[newX][newY] || maze[newX][newY] == 1) {
                continue;
            }
            queue.offer(new int[]{newX, newY});
            visited[newX][newY] = true;
        }
    }

    return "cannot be travelled";
}

