            if (word1.charAt(i) == word2.charAt(j)) {
                commonLettersCount++;
                break;
            }
        }
    }

    if (commonLettersCount == 0) {
        BigInteger resultN = BigInteger.ONE;
        BigInteger resultD = BigInteger.ONE;
        return "appx(" + word1 + ", " + word2 + ") = " + resultN + "/" + resultD;
    }

    BigInteger numerator = BigInteger.valueOf(commonLettersCount);
    BigInteger denominator = BigInteger.valueOf(totalLength);

    BigInteger gcd = numerator.gcd(denominator);
    numerator = numerator.divide(gcd);
