public static double trimMean(int[] arr) {
        Arrays.sort(arr);
        int trimSize = arr.length / 20; // 5% of the length of the array
        List<Integer> trimmedArray = Arrays.asList(arr).subList(trimSize, arr.length - trimSize);
        double sum = 0;
        for (int num : trimmedArray)
            sum += num;
        return sum / trimmedArray.size();
    }

public double trimMean(int[] arr) {
        Arrays.sort(arr);
        int n = arr.length;
        inttrimSize = n * 5 / 100;

        double sum = 0;
        int totalValidElements = 0;
        for (int i = trimSize; i < n - trimSize; i++) {
            sum += arr[i];
            totalValidElements++;
        }

        return sum / totalValidElements;
    }

public static double trimMean(int[] arr) {
        int totalElements = arr.length;
        int leftElementsToRemove = totalElements / 20;
        int rightElementsToRemove = totalElements / 20;

        Arrays.sort(arr);
        int[] modifiedArr = Arrays.stream(arr).skip(leftElementsToRemove).limit(totalElements - (leftElementsToRemove + rightElementsToRemove))
                                         .toArray();

        double average = Arrays.stream(modifiedArr).average().orElse(Double.NaN);
        return average;
    }

