public double trimMean(int[] arr) {
        int N = arr.length;
        // Ensure the array size is at least 4 to handle the trimming conditions
        if (N < 4) {
            throw new IllegalArgumentException("Array size must be at least 4.");
        }

        // Sort the array to easily identify the 5th and 50th percentile values
        Arrays.sort(arr);

        // Calculate the size of the smaller half of the array
        int trimmedSize = N / 10;

        // Calculate the sum of the trimmed elements
        double sum = 0;
        for (int i = trimmedSize; i < N - trimmedSize; i++) {
            sum += arr[i];
        }

        // Calculate the mean of the trimmed elements
        return sum / (N - 2 * trimmedSize);
    }

public boolean canArrange(int[] arr, int k) {
        Arrays.sort(arr);
        int sum = 0;
        for (int i = 0; i < arr.length; i++) {
            sum += arr[i];
        }
        if (sum % k != 0) {
            return false;
        }
        for (int i = 0; i < arr.length; i += 2) {
            if (arr[i] % k != 0) {
                return false;
            }
        }
        int len = arr.length / 2;
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j < len; j++) {
                if ((arr[j] - arr[i]) % k == 0) {
                    return false;
                }
            }
        }
        return true;
    }

public boolean canArrange(int[] arr, int k) {
    int len = arr.length;
    if (len % 2 != 0) {
        return false;
    }

    int[] remainder = new int[k];
    for (int num : arr) {
        remainder[num % k]++;
    }

    for (int i = 1; i < k; i++) {
        if (remainder[i] != remainder[k - i]) {
            return false;
        }
    }

    if (remainder[0] % 2 != 0) {
        if (k % 2 == 0) {
            return false;
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr.length % 2 != 0) {
        return false; // Odd number of elements cannot be paired
    }
    int[] frequencies = new int[k];
    for (int num : arr) {
        frequencies[num % k]++;
    }
    int oddCount = 0;
    for (int freq : frequencies) {
        if (freq % 2 != 0) {
            oddCount++;
        }
    }
    return oddCount <= 1;
}

