        if (arr.length % 2 != 0) {
            return false;
        }

        Map<Integer, Integer> map = new HashMap<>();
        for (int num : arr) {
            int remainder = num % k;
            if (map.containsKey(remainder)) {
                if (remainder == 0 || map.get(remainder) == 0) {
                    return true;
                }
            }
            map.put(remainder, map.getOrDefault(remainder, 0) + 1);
        }
        return false;
    }

public boolean canArrange(int[] arr, int k) {
    int remainderMap[] = new int[k];
    for (int num : arr) {
        remainderMap[num % k]++;
    }
    int oddCount = 0;
    for (int absence : remainderMap) {
        if (absence % 2 == 1) oddCount++;
    }
    return oddCount <= 1;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
        List<List<Integer>> graph = buildGraph(edges);

        int totalTime = 0;
        HashSet<Integer> visited = new HashSet<>();
        for (int i = 0; i < graph.size(); i++) {
            if (!visited.contains(i)) {
                totalTime += traverse(graph, i, hasApple, visited);
            }
        }

        return totalTime;
    }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
        // Build adjacency list
        List<Integer>[] adj = new List[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            adj[edge[0]].add(edge[1]);
            adj[edge[1]].add(edge[0]);
        }

        // Use a queue for BFS
        Queue<Integer> queue = new LinkedList<>();
        queue.offer(0);
        boolean[] visited = new boolean[n];
        visited[0] = true;

        // Perform BFS to collect apples
        int totalTime = 0;
        while (!queue.isEmpty()) {
            int current = queue.poll();
            for (int neighbor : adj[current]) {
                if (!visited[neighbor]) {
                    visited[neighbor] = true;
                    if (hasApple[neighbor]) {
                        totalTime += 2; // Time for traveling to and returning from the neighbor
                    }
                    queue.offer(neighbor);
                }
            }
        }

        return totalTime;
    }

