public int minTime(int n, int[][] edges, boolean[] hasApple) {
    Map<Integer, List<Integer>> graph = new HashMap<>();
    for (int[] edge : edges) {
        int u = edge[0], v = edge[1];
        graph.computeIfAbsent(u, k -> new ArrayList<>()).add(v);
        graph.computeIfAbsent(v, k -> new ArrayList<>()).add(u);
    }

    boolean[] visited = new boolean[n];
    int time = 0;

    Queue<int[]> queue = new LinkedList<>();
    queue.offer(new int[]{0, 0});

    while (!queue.isEmpty()) {
        int[] node = queue.poll();
        int distance = node[0], parent = node[1];

        visited[node[0]] = true;

        if (hasApple[node[0]]) {
            time += 2 + (distance - 1) * 2;
        }

        if (graph.containsKey(node[0])) {
            for (int neighbor : graph.get(node[0])) {
                if (!visited[neighbor]) {
                    queue.offer(new int[]{neighbor, node[0]});
                }
            }
        }
    }

    return time;
}

public String sortString(String s) {
    if (s.isEmpty()) {
        return "";
    }

    StringBuilder result = new StringBuilder();
    Arrays.sort(s.toCharArray());

    int mid = s.length() / 2;

    String left = s.substring(0, mid + 1);
    String right = s.substring(mid + 1);

    for (int i = 0, j = 0, k = 0; i < s.length(); i++) {
        if (i % 2 == 0) {
            if (left[j] < right[k]) {
                result.append(left[j++]);
            } else {
                result.append(right[k++]);
            }
        } else {
            if (left[j] < right[k]) {
                result.append(right[k++]);
            } else {
                result.append(left[j++]);
            }
        }
    }

    return result.toString();
}

public String sortString(String s) {
    int[] counts = new int[26];
    for (char c : s.toCharArray()) {
        counts[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    int size = s.length();
    char[] smallestChars = new char[size];
    char[] largestChars = new char[size];
    int smallestPointer = 0;
    int largestPointer = 0;

    // Step 1-6: Append the smallest and largest characters to the result
    while (result.length() < size) {
        if (smallestPointer < size && (largestPointer == size || counts[smallestChars[smallestPointer] - 'a'] < counts[largestChars[largestPointer] - 'a'])) {
            result.append(smallestChars[smallestPointer]);
            smallestPointer++;
        } else {
            result.append(largestChars[largestPointer]);
            largestPointer++;
        }
    }

    return result.toString();
}

public String sortString(String s) {
    Map<Character, Integer> charCountMap = new HashMap<>();
    for (char c : s.toCharArray()) {
        charCountMap.put(c, charCountMap.getOrDefault(c, 0) + 1);
    }

    StringBuilder resultList = new StringBuilder();

    // Pick the smallest character and append it
    Map.Entry<Character, Integer> smallestCharEntry = charCountMap.entrySet().stream()
            .min(Map.Entry.comparingByKey());
    if (smallestCharEntry != null && smallestCharEntry.getValue() > 0) {
        resultList.append(smallestCharEntry.getKey());
        charCountMap.remove(smallestCharEntry.getKey());
    }

    // Pick the smallest character greater than the last appended character
    StringBuilder additionalSmallChars = new StringBuilder();
    for (Map.Entry<Character, Integer> entry : charCountMap.entrySet()) {
        additionalSmallChars.append(entry.getKey());
        charCountMap.remove(entry.getKey());
    }

    while (!additionalSmallChars.isEmpty()) {
        Character smallChar = additionalSmallChars.charAt(0);
        additionalSmallChars.deleteCharAt(0);
        resultList.append(smallChar);
        if (charCountMap.containsKey(smallChar)) {
            charCountMap.put(smallChar, charCountMap.get(smallChar) - 1);
        }
    }

    // Pick the largest character and append it
    Map.Entry<Character, Integer> largestCharEntry = charCountMap.entrySet().stream()
            .max(Map.Entry.comparingByKey().reversed());
    if (largestCharEntry != null && largestCharEntry.getValue() > 0) {
        resultList.append(largestCharEntry.getKey());
        charCountMap.remove(largestCharEntry.getKey());
    }

    // Pick the largest character smaller than the last appended character
    additionalSmallChars = new StringBuilder();
    for (Map.Entry<Character, Integer> entry : charCountMap.entrySet()) {
        additionalSmallChars.append(entry.getKey());
        charCountMap.remove(entry.getKey());
    }

    while (!additionalSmallChars.isEmpty()) {
        Character largeChar = additionalSmallChars.charAt(0);
        additionalSmallChars.deleteCharAt(0);
        resultList.append(largeChar);
        if (charCountMap.containsKey(largeChar)) {
            charCountMap.put(largeChar, charCountMap.get(largeChar) - 1);
        }
    }

    return resultList.toString();
}

public String sortString(String s) {
        if (s == null || s.length() <= 1) {
            return s;
        }

        PriorityQueue<Character> minHeap = new PriorityQueue<>();
        PriorityQueue<Character> maxHeap = new PriorityQueue<>((a, b) -> b - a);

        // Populate minHeap with characters from s
        for (char c : s.toCharArray()) {
            minHeap.add(c);
        }

        StringBuilder sortedString = new StringBuilder();

        while (!minHeap.isEmpty() || !maxHeap.isEmpty()) {
            if (!minHeap.isEmpty()) {
                char minChar = minHeap.poll();
                sortedString.append(minChar);
                if (minHeap.isEmpty()) {
                    break;
                }
                // If the maximum element is the same as the recently added minimum element,
                // it needs to be counted again by an additional -1
                while (!maxHeap.isEmpty() && minHeap.peek() == maxHeap.peek()) {
                    sortedString.append(minHeap.poll());
                }
            }

            if (!maxHeap.isEmpty()) {
                char maxChar = maxHeap.poll();
                sortedString.append(maxChar);
                if (maxHeap.isEmpty()) {
                    break;
                }
                // If the minimum element is the same as the recently added maximum element,
                // it needs to be counted again by an additional -1
                while (!minHeap.isEmpty() && maxHeap.peek() == minHeap.peek()) {
                    sortedString.append(minHeap.poll());
                }
            }
        }

        return sortedString.toString();
    }

public String sortString(String s) {
    if (s == null || s.length() <= 1) {
        return s;
    }

    StringBuilder result = new StringBuilder();
    int[] charCounts = new int[26]; // Alphabetical order: a - z

    // Count the occurrences of each character
    for (char c : s.toCharArray()) {
        charCounts[c - 'a']++;
    }

    int left = 0, right = 25;
    boolean reverse = true;

    while (!isAllZero(charCounts)) {
        if (reverse) {
            for (int i = left; i <= right; i++) {
                while (charCounts[i] > 0) {
                    result.append((char) ('a' + i));
                    charCounts[i]--;
                }
            }
            reverse = false;
        } else {
            for (int i = right; i >= left; i--) {
                while (charCounts[i] > 0) {
                    result.append((char) ('a' + i));
                    charCounts[i]--;
                }
            }
            reverse = true;
        }
        left++;
        right--;
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int totalSum = Arrays.stream(nums).sum();
    if (totalSum % 2 != 0) {
        return false; // If total sum is odd, a valid split is impossible
    }

    int avg = totalSum / 2;
    int n = nums.length;

    int left = 0, right = n - 1;
    int totalLeft = 0, totalRight = 0;

    // Check if there exists a subarray with the sum equal to avg
    while (left <= right) {
        if (totalLeft > avg || totalRight < avg) {
            return false; // Current subarrays don't have equal sum to avg
        }
        if (totalLeft == avg && totalRight == avg) {
            return true; // A valid split is found
        }
        if (totalLeft < avg) {
            totalLeft += nums[left++];
        } else {
            totalRight += nums[right--];
        }
    }

    return false; // No valid split found
}

public boolean splitArraySameAverage(int[] nums) {
        if (nums == null || nums.length <= 1) {
            return false;
        }

        Arrays.sort(nums);
        int n = nums.length;
        double totalSum = sum(nums);
        double maxPossibleSum = totalSum / 2;

        for (int partitionSize = 1; partitionSize <= n / 2; partitionSize++) {
            double maxSubarraySum = sum(nums, 0, partitionSize - 1);
            if (maxSubarraySum > maxPossibleSum) {
                break;
            }
            double otherSubarraySum = totalSum - maxSubarraySum;
            if (otherSubarraySum % partitionSize == 0) {
                return true;
            }
        }

        return false;
    }

public boolean splitArraySameAverage(int[] nums) {
        if (nums == null || nums.length < 2) {
            return false;
        }

        int sum = Arrays.stream(nums).sum();
        int n = nums.length;

        for (int i = 1; i < n; i++) {
            if (sum % i != 0) {
                continue;
            }

            int target = sum / i;
            boolean[](dp = new boolean[target + 1]) {
                dp[0] = true;
            }

            for (int num : nums) {
                for (int j = target; j > 0; j--) {
                    if (dp[j]) {
                        dp[j - num] = true;
                        if (j == num) {
                            dp[j] = false;
                        }
                    }
                }
            }

            if (dp[target]) {
                return true;
            }
        }

        return false;
    }

public boolean splitArraySameAverage(int[] nums) {
        int totalSum = Arrays.stream(nums).sum();
        int n = nums.length;
        // If the total sum is odd, splitting into equal averages is not possible
        if (totalSum % n != 0) {
            return false;
        }

        double avg = totalSum / n;

        int[] prefixSums = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            prefixSums[i] = prefixSums[i - 1] + nums[i - 1];
        }

        // Check if there exists an index i such that prefixSums[i] * (n - i) == avg * n
        return Arrays.stream(prefixSums).anyMatch(prefixSum -> prefixSum * (n - prefixSum) == avg * n);
    }

public boolean splitArraySameAverage(int[] nums) {
    int totalSum = Arrays.stream(nums).sum();
    int numLen = nums.length;

    for (int i = 0; i < (numLen + 1) / 2; i++) {
        if (totalSum * (i + 1) % numLen == 0) {
            int targetSum = totalSum * (i + 1) / numLen;
            int[] leftSum = new int[i + 1];
            int sum = 0;
            for (int j = 0; j < leftSum.length; j++) {
                sum += nums[j];
                if (sum == targetSum) {
                    return true;
                }
                leftSum[j] = sum;
            }
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i-1], dp[i-2]);
    }

    return Math.min(dp[n-1], dp[n-2]);
}

public int minCostClimbingStairs(int[] cost) {
        int n = cost.length;
        if (n == 0) return 0;
        if (n == 1) return cost[0];

        int[] dp = new int[n];
        dp[0] = cost[0];
        dp[1] = cost[1];

        for (int i = 2; i < n; i++) {
            dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
        }

        return Math.min(dp[n - 1], dp[n - 2]);
    }

public int minCostClimbingStairs(int[] cost) {
        if (cost.length <= 2) {
            return Math.min(cost[0], cost[1]);
        }

        int[] dp = new int[cost.length];
        dp[0] = cost[0];
        dp[1] = cost[1];

        for (int i = 2; i < cost.length; i++) {
            dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
        }

        return Math.min(dp[cost.length - 1], dp[cost.length - 2]);
    }

public int minCostClimbingStairs(int[] cost) {
        if (cost.length == 0) return 0;
        if (cost.length == 1) return cost[0];
        if (cost.length == 2) return Math.min(cost[0], cost[1]);

        Arrays.fill(cost, cost[0]);
        cost[1] = Math.min(cost[0], cost[1]) + cost[1];

        for (int i = 2; i < cost.length; i++) {
            cost[i] = Math.min(cost[i - 1], cost[i - 2]) + cost[i];
        }

        return Math.min(cost[cost.length - 2], cost[cost.length - 1]);
    }

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int dfs = Math.max((Math.max(cost[0], cost[1])), cost[2]);
    for (int i = 3; i < cost.length; i++) {
        dfs = Math.max(((Math.max(dfs, cost[0]) + Math.max(dfs, cost[1])), cost[i]));
    }
    return dfs;
}

