public boolean hasAllCodes(String s, int k) {
    int mask = 0;
    for (int i = 0; i < k; i++) {
        mask <<= 1;
        mask |= 1;
    }
    for (int i = k; i <= s.length() - k; i++) {
        int windowMask = 0;
        for (int j = i; j < i + k; j++) {
            windowMask <<= 1;
            windowMask |= s.charAt(j) == '1' ? 1 : 0;
        }
        if ((mask & windowMask) == 0) {
            return false;
        }
    }
    return true;
}

public static boolean hasAllCodes(String s, int k) {
        int setSize = 1 << k; // Number of possible substrings of length k
        HashSet<String> substringSet = new HashSet<>();

        for (int i = 0; i <= s.length() - k; i++) {
            String currentSubstring = s.substring(i, i + k);
            substringSet.add(currentSubstring);
            if (substringSet.size() == setSize) {
                return true;
            }
        }

        return substringSet.size() == setSize;
    }

public boolean hasAllCodes(String s, int k) {
    Set<String> set = new HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
        String sub = s.substring(i, i + k);
        if (!set.contains(sub)) {
            set.add(sub);
        } else {
            return false;
        }
    }
    return true;
}

