public int minInsertions(String s) {
    int balance = 0;
    int insertions = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            balance++;
        } else {
            if (balance > 0) {
                balance--;
            } else {
                insertions++;
            }
        }
    }

    return insertions + balance;
}

public int minInsertions(String s) {
    int open = 0;
    int close = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') open++;
        else close++;
        if (close > open) open++;
        else close = 0;
    }

    // If close is greater than open, we need to insert enough ')' to balance the string
    return close + open;
}

