public int maxAbsoluteSum(int[] nums) {
        int n = nums.length;
        int leftSum = 0, rightSum = 0, maxSum = 0;

        for (int i = 0; i < n; i++) {
            leftSum = Math.max(0, leftSum + nums[i]);
            rightSum = Math.max(0, rightSum + nums[n - 1 - i]);
            maxSum = Math.max(maxSum, Math.max(leftSum, rightSum) + nums[i]);
        }

        return maxSum;
    }

public int maxAbsoluteSum(int[] nums) {
    int maxPositiveSum = Integer.MIN_VALUE;
    int maxNegativeSum = Integer.MAX_VALUE;
    int totalSum = 0;

    for (int num : nums) {
        totalSum += num;
        maxPositiveSum = Math.max(maxPositiveSum, totalSum);
        maxNegativeSum = Math.min(maxNegativeSum, totalSum);
    }

    return Math.max(Math.abs(maxPositiveSum), Math.abs(maxNegativeSum));
}

public int maxAbsoluteSum(int[] nums) {
    int n = nums.length;

    // Array to store maximum and minimum sums ending at each position
    int[] maxEnd = new int[n];
    int[] minEnd = new int[n];

    // Initialize the first element of both arrays
    maxEnd[0] = minEnd[0] = nums[0];

    for (int i = 1; i < n; i++) {
        // Update maximum end value at i
        maxEnd[i] = Math.max(nums[i], maxEnd[i - 1] + nums[i]);
        // Update minimum end value at i
        minEnd[i] = Math.min(nums[i], minEnd[i - 1] + nums[i]);
    }

    // Find the maximum absolute sum
    int maxAbsoluteSum = 0;
    for (int i = 0; i < n; i++) {
        maxAbsoluteSum = Math.max(maxAbsoluteSum, maxEnd[i] - minEnd[i]);
    }

    return maxAbsoluteSum;
}

public int maxAbsoluteSum(int[] nums) {
    int maxSum = Integer.MIN_VALUE;
    int minSum = Integer.MAX_VALUE;

    int currentSum = 0;
    for(int num: nums) {
        currentSum += num;
        if(currentSum > maxSum) {
            maxSum = currentSum;
        }
        if(currentSum < minSum) {
            minSum = currentSum;
        }
    }

    return Math.abs(maxSum - minSum);
}

public static int maxAbsoluteSum(int[] nums) {
    int maxSum = 0;
    int currentSum = 0;

    if (nums.length <= 0) {
        return maxSum;
    }

    for (int num : nums) {
        currentSum = Math.max(0, currentSum + num);
        maxSum = Math.max(maxSum, currentSum);
    }

    for (int num : nums) {
        currentSum = Math.min(0, currentSum + num);
        maxSum = Math.max(maxSum, currentSum);
    }

    return maxSum;
}

