public int findMinFibonacciNumbers(int k) {
    List<Integer> fibSequence = new ArrayList<>();
    fibSequence.add(0);
    fibSequence.add(1);
    int nextFib = 1;
    while (nextFib <= k) {
        fibSequence.add(nextFib);
        nextFib = fibSequence.get(fibSequence.size() - 1) + fibSequence.get(fibSequence.size() - 2);
    }
    Collections.sort(fibSequence);

    int count = 0;
    int index = fibSequence.size() - 1;
    while (k > 0) {
        if (k >= fibSequence.get(index)) {
            k -= fibSequence.get(index);
            count++;
        } else {
            index--;
        }
    }

    return count;
}

public int findMinFibonacciNumbers(int k) {
    List<Integer> fibs = new ArrayList<>();
    int current = 1;
    while (current <= k) {
        fibs.add(current);
        current += fibs.get(fibs.size() - 2);
    }

    int result = 0;
    for (int i = fibs.size() - 1; i >= 0 && k > 0; i--) {
        if (k >= fibs.get(i)) {
            k -= fibs.get(i);
            result++;
        }
    }

    return result;
}

public static int findMinFibonacciNumbers(int k) {
        List<Integer> fibNumbers = new ArrayList<>();
        fibNumbers.add(1);
        fibNumbers.add(1);

        while (true) {
            int nextFib = fibNumbers.get(fibNumbers.size() - 1) + fibNumbers.get(fibNumbers.size() - 2);
            if (nextFib > k) {
                break;
            }
            fibNumbers.add(nextFib);
        }

        int count = 0;
        for (int fib : fibNumbers) {
            while (k >= fib) {
                count++;
                k -= fib;
            }
        }
        return count;
    }

public int findMinFibonacciNumbers(int k) {
    int[] fib = {0, 1};
    int i = 2;
    while (true) {
        if (fib[i] >= k) {
            break;
        }
        fib[i] = fib[i - 1] + fib[i - 2];
        i++;
    }
    int count = 0;
    for (int j = i - 1; j >= 0; j--) {
        while (k >= fib[j]) {
            k -= fib[j];
            count++;
        }
    }
    return count;
}

