public int kthFactor(int n, int k) {
    int count = 0;
    for (int i = 1; i <= Math.sqrt(n); i++) {
        if (n % i == 0) {
            count++;
            if (count == k) {
                return i;
            }
            if (i != n / i) {
                count++;
                if (count == k) {
                    return n / i;
                }
            }
        }
    }
    return -1;
}

public String makeGood(String s) {
          Stack<Character> stack = new Stack<>();
          for (char c : s.toCharArray()) {
              if (stack.isEmpty() || Math.abs((int) c - (int) stack.peek()) != 32) {
                  stack.push(c);
              } else {
                  stack.pop();
              }
          }
          StringBuilder result = new StringBuilder();
          while (!stack.isEmpty()) {
              result.insert(0, stack.pop());
          }
          return result.toString();
    }

public String makeGood(String s) {
        StringBuilder sb = new StringBuilder();
        for(char c : s.toCharArray()){
            if(!sb.isEmpty() && Math.abs(sb.charAt(sb.length() - 1) - c) == 32){
                sb.deleteCharAt(sb.length() - 1);
            } else {
                sb.append(c);    
            }
        }

        return sb.toString();
    }

public String makeGood(String s) {
    if (s.length() <= 1) {
        return s;
    }

    StringBuilder sb = new StringBuilder(s);

    for (int i = 0; i < sb.length() - 1; i++) {
        char current = sb.charAt(i);
        char next = sb.charAt(i + 1);

        if (Math.abs(current - next) == 32) { // Check if the characters are adjacent lowercase and uppercase
            sb.deleteCharAt(i); // Remove the current character and the next character
            sb.deleteCharAt(i); // Remove the next character (already handled)
            i -= 2; // Adjust index to consider the deleted characters
        }
    }

    return sb.toString();
}

public String makeGood(String s) {
    if (s == null || s.length() <= 1) return s;

    Stack<Character> stack = new Stack<>();

    for (char c : s.toCharArray()) {
        if (!stack.isEmpty() && Character.toUpperCase(stack.peek()) == c) {
            stack.pop();
        } else {
            stack.push(c);
        }
    }

    StringBuilder sb = new StringBuilder();
    while (!stack.isEmpty()) {
        sb.append(stack.pop());
    }
    return sb.reverse().toString();
}

public String makeGood(String s) {
    StringBuilder sb = new StringBuilder();
    int prev = -1;
    for (int i = 0; i < s.length(); i++) {
        if (prev >= 0 && Math.abs(prev - i) == 1 && Character.toLowerCase(s.charAt(prev)) == Character.toLowerCase(s.charAt(i))) {
            sb.deleteCharAt(prev--);
        } else {
            sb.append(s.charAt(i));
            prev = i;
        }
    }
    return sb.toString();
}

