        return 0;
    }

    int max = 0;
    Set<String> unique = new HashSet<>();
    for (int i = 0; i < s.length(); i++) {
        for (int j = i + 1; j <= s.length(); j++) {
            String sub = s.substring(i, j);
            if (unique.contains(sub)) {
