    int count = 0;
    List<String> currentSubstrings = new ArrayList<>();
    int start = 0;

    while (start < s.length()) {
        for (int end = start; end < s.length(); end++) {
            String currentString = s.substring(start, end + 1);
            if (currentSubstrings.contains(currentString)) {
                break;
            } else {
                currentSubstrings.add(currentString);
                count++;
            }
        }
        start++;
    }

    return count;
}

public int maxUniqueSplit(String s) {
    int maxUnique = 0;
    Set<String> visited = new HashSet<>();

    for (int i = 0; i < s.length(); i++) {
        visited.clear();
        visited.add(String.valueOf(s.charAt(i)));
        for (int j = i + 1; j < s.length(); j++) {
            String substr = s.substring(i, j + 1);
            if (!visited.contains(substr)) {
                visited.add(substr);
                maxUnique += 1;
            } else {
                break;
            }
        }
    }

    // Include the entire string as a separate subtring
    visited.add(s);
    maxUnique += 1;

    return maxUnique;
}

