    int m = mat.length;
    int n = mat[0].length;

    int maxLen = 0;
    int numRows = m + n - 1;
    boolean[][] dp = new boolean[numRows][numRows];

    for (int i = 0; i < numRows; i++) {
        Arrays.fill(dp[i], false);
    }

    for (int i = m - 1; i >= 0; i--) {
        for (int j = n - 1; j >= 0; j--) {
            if (mat[i][j] == 1) {
                // Check horizontal
                if (i + 1 < m && mat[i + 1][j] == 1) {
                    dp[i][j] = true;
                    dp[i + 1][j] = true;
                }
                // Check vertical
                if (j + 1 < n && mat[i][j + 1] == 1) {
                    dp[i][j] = true;
                    dp[i][j + 1] = true;
                }
                // Check diagonal
                if (i + 1 < m && j + 1 < n && mat[i + 1][j + 1] == 1) {
                    dp[i][j] = true;
                    dp[i + 1][j + 1] = true;
                }
                // Check anti-diagonal
                if (i + 1 < m && j - 1 >= 0 && mat[i + 1][j - 1] == 1) {
                    dp[i][j] = true;
                    dp[i + 1][j - 1] = true;
                }

                if (dp[i][j]) {
                    maxLen = Math.max(maxLen, i + j + 1);
                }
            }
        }
    }

    return maxLen;
}

