        return 0;
    }

    // Rows and cols of the matrix
    int rows = mat.length;
    int cols = mat[0].length;

    // DP tables for counting 1s in different directions
    int [][] vertical = new int[rows][cols];
    int [][] horizontal = new int[rows][cols];
    int [][] diagonal = new int[rows][cols];
    int [][] antiDiagonal = new int[rows][cols];

    if (mat[0][0] == 1) {
        vertical[0][0] = 1;
        horizontal[0][0] = 1;
        diagonal[0][0] = 1;
        antiDiagonal[0][0] = 1;
    }

    int maxLength = 1;

    // Fill the DP tables
    for (int i = 1; i < rows; i++) {
        if (mat[i][0] == 1) {
            vertical[i][0] = vertical[i - 1][0] + 1;
            horizontal[i][0] = 1;
            diagonal[i][0] = 1;
            antiDiagonal[i][0] = 1;
        }
    }

    for (int j = 1; j < cols; j++) {
        if (mat[0][j] == 1) {
            horizontal[0][j] = horizontal[0][j - 1] + 1;
            vertical[0][j] = 1;
            diagonal[0][j] = 1;
            antiDiagonal[0][j] = 1;
        }
    }

    for (int i = 1; i < rows; i++) {
        for (int j = 1; j < cols; j++) {
            if (mat[i][j] == 1) {
                vertical[i][j] = vertical[i - 1][j] + 1;
                horizontal[i][j] = horizontal[i][j - 1] + 1;
                diagonal[i][j] = diagonal[i - 1][j - 1] + 1;
                antiDiagonal[i][j] = antiDiagonal[i - 1][j + 1] + 1;

                maxLength = Math.max(maxLength, vertical[i][j]);
                maxLength = Math.max(maxLength, horizontal[i][j]);
                maxLength = Math.max(maxLength, diagonal[i][j]);
                maxLength = Math.max(maxLength, antiDiagonal[i][j]);
            }
        }
    }

