        Arrays.fill(nextSmaller, height.length);
        Arrays.fill(prevSmaller, -1);

        // Find index of closest smaller element to the left of each element
        for (int i = 0; i < height.length; i++) {
            while (prevSmaller[i] >= 0 && height[i] <= height[prevSmaller[i]]) {
                prevSmaller[i] = prevSmaller[prevSmaller[i]];
            }
        }

        // Find index of closest smaller element to the right of each element
        for (int i = height.length - 1; i >= 0; i--) {
            while (nextSmaller[i] < height.length && height[i] <= height[nextSmaller[i]]) {
                nextSmaller[i] = nextSmaller[nextSmaller[i]];
            }
        }

        int maxArea = 0;
        for (int i = 0; i < height.length; i++) {
            int width = nextSmaller[i] - prevSmaller[i] - 1;
            int area = height[i] * width;
            maxArea = Math.max(maxArea, area);
        }

        return maxArea;
    }

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    Stack<Integer> stack = new Stack<>();

    int i = 0;
    while (i < heights.length) {
        while (!stack.isEmpty() && heights[i] < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            maxArea = Math.max(maxArea, area);
        }
        stack.push(i++);
    }

    while (!stack.isEmpty()) {
        int height = heights[stack.pop()];
        int width = stack.isEmpty() ? i : i - stack.peek() - 1;
        int area = height * width;
        maxArea = Math.max(maxArea, area);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];

    int i = 0, j = 0, curIdx = 0;

    // Traverse in a right diagonal pattern
    while(i < rows && j < cols) {
        result[curIdx++] = mat[i][j];

        if(j == cols - 1) {
            i++;
        } else if(i == 0) {
            j++;
        } else {
            i--;
            j++;
        }
    }

    // Traverse in a top diagonal pattern
    if(rows > 1) {
        i = 1;
        j = 0;
        while(i < rows && j < cols) {
            result[curIdx++] = mat[i][j];

            if(i == rows - 1) {
                j++;
            } else if(j == 0) {
                i++;
            } else {
                i++;
                j--;
            }
        }
    }

    return result;
}

