    if (mat == null || mat.length == 0 || mat[0].length == 0) return new int[0];

    int m = mat.length, n = mat[0].length;
    int[] result = new int[m * n];
    int i = 0, j = 0;
    int dir = 0; // 0: down, 1: right

    while (i >= 0 && i < m && j >= 0 && j < n) {
        result[i * n + j] = mat[i][j];
        if (dir == 0) {
            if (j == n - 1) i++;
            else j++;
        } else {
            if (i == m - 1) j++;
            else i++;
        }
        dir = 1 - dir;
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    int rowLength = mat.length;
    int columnLength = mat[0].length;
    int[] res = new int[rowLength * columnLength];

    for(int d = 0; d < rowLength + columnLength - 1; d++) {
        int i = Math.max(0, d - columnLength + 1);
        int j = 0;

        if(d < columnLength) {
            j = d;
        }

        while(i < rowLength && j < columnLength) {
            res[d] = mat[i][j];
            i++;
            j++;
        }

        if(d < rowLength + columnLength - 1) {
            i--;
            j--;

            while(i >= 0 && j >= 0) {
                res[d++] = mat[i][j];
                i--;
                j--;
            }
        }
    }
    return res;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }

    char[] digits = String.valueOf(n).toCharArray();
    for (int i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            // Find the smallest digit to the right of i that is greater than digits[i]
            int j = digits.length - 1;
            while (digits[j] <= digits[i]) {
                j--;
            }
            // Swap digits[i] and digits[j]
            char temp = digits[i];
            digits[i] = digits[j];
            digits[j] = temp;
            // Sort the remaining digits in ascending order
            Arrays.sort(digits, i + 1, digits.length);
            // Convert the sorted array of characters back to an integer
            return Integer.parseInt(new String(digits));
        }
    }
    return -1;
}

