    for (int i = 0; i < digits.length; i++) {
        if (i < digits.length - 1) {
            int j = i + 1;
            // Find the smallest digit to the right of i that is greater than digits[i]
            while (j < digits.length && digits[j] <= digits[i]) {
                j++;
            }
            // Swap digits[i] and digits[j]
            char temp = digits[i];
            digits[i] = digits[j];
            digits[j] = temp;
            // Break the loop as we have found the smallest permutation
            break;
        }
    }

    // Convert the sorted digits back to an integer
    long smallestInt = Long.parseLong(String.valueOf(digits));

