public static boolean isBoomerang(int[][] points) {
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // If a point's x-coordinate is the same as another point's x-coordinate and their y-coordinates are different, then the points are collinear.
    if ((x2 == x1 && y2 != y1) || (x3 == x1 && y3 != y1)) {
        return false;
    }

    // Calculate the area of the triangle formed by the points using the determinant formula.
    double area = 0.5 * Math.abs(x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2));
    // If the area is zero, then the points are collinear, and thus not a boomerang.
    return area != 0;
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        throw new IllegalArgumentException("The array must contain exactly 3 points.");
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Check if all points are collinear
    if (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2) == 0) {
        return false;
    }

    // Check if the points form a straight line (collinear)
    if ((x1 - x2) * (x3 - x2) == 0 || (y1 - y2) * (y3 - y2) == 0) {
        return false;
    }

    return true;
}

public static boolean isBoomerang(int[][] points) {
    // Check if the length of the points array is not 3
    if (points.length != 3) return false;

    // Calculate the differences between consecutive points
    int dx1 = points[1][0] - points[0][0];
    int dy1 = points[1][1] - points[0][1];
    int dx2 = points[2][0] - points[1][0];
    int dy2 = points[2][1] - points[1][1];

    // Check if the points form a right triangle with sides dx1, dy1, and dx2, dy2
    return dx1 * dy2 != dx2 * dy1;
}

