    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    int i2 = 0, i3 = 0, i5 = 0;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(uglyNumbers[i2] * 2, Math.min(uglyNumbers[i3] * 3, uglyNumbers[i5] * 5));
        uglyNumbers[i] = nextUgly;

        if (nextUgly == uglyNumbers[i2] * 2) i2++;
        if (nextUgly == uglyNumbers[i3] * 3) i3++;
        if (nextUgly == uglyNumbers[i5] * 5) i5++;
    }

    return uglyNumbers[n - 1];
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        return 0;
    }
    PriorityQueue<Integer> pq = new PriorityQueue<>(n);
    pq.offer(1);
    Set<Integer> visited = new HashSet<>();
    visited.add(1);

    for (int a = 1; a <= n; a++) {
        int cur = pq.poll();
        for (int multi : new int[]{2, 3, 5}) {
            int next = cur * multi;
            if (visited.add(next)) {
                pq.offer(next);
            }
        }
    }
    return pq.poll();
}

