    dp[0] = 0;

    // Fill dp array
    for (int i = 1; i <= n; i++) {
        dp[i] = i;
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    for (int i = 1; i * i <= n; i++) {
        if (n == i * i) {
            return 1;
        } else if (n > i * i) {
            return minPerfectSquareSum(n - i * i);
        }
    }
    return n; // If no perfect square sum is found, which should never happen for this problem
}

