public static String reverseWords(String s) {
        String[] words = s.split(" ");
        StringBuilder result = new StringBuilder();

        for (String word : words) {
            StringBuilder reversedWord = new StringBuilder();
            for (int i = word.length() - 1; i >= 0; i--) {
                reversedWord.append(word.charAt(i));
            }
            result.append(reversedWord.toString());
            result.append(" ");
        }

        return result.toString().trim();
    }

public static String reverseWords(String s) {
    StringBuilder result = new StringBuilder();
    StringBuilder currentWord = new StringBuilder();

    for (int i = 0; i <= s.length(); i++) {
        if (i == s.length() || s.charAt(i) == ' ') {
            if (!currentWord.isEmpty()) {
                reverse(currentWord);
                result.append(currentWord.toString());
                currentWord.setLength(0);
            }
            if (i < s.length()) {
                result.append(' ');
            }
        } else {
            currentWord.append(s.charAt(i));
        }
    }

    return result.toString();
}

public static String reverseWords(String s) {
    StringBuilder reversedSentence = new StringBuilder();
    int start = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == ' ') {
            reversedSentence.append(new StringBuilder(s.substring(start, i)).reverse().toString()).append(" ");
            start = i + 1;
        } else if (i == s.length() - 1) {
            reversedSentence.append(new StringBuilder(s.substring(start, i + 1)).reverse().toString());
        }
    }

    return reversedSentence.toString().trim();
}

public static String reverseWords(String s) {
    StringBuilder result = new StringBuilder();
    for (String word : s.split(" ")) {
        StringBuilder reversedWord = new StringBuilder();
        for (int i = word.length() - 1; i >= 0; i--) {
            reversedWord.append(word.charAt(i));
        }
        result.append(reversedWord).append(" ");
    }
    return result.toString().trim();
}

public static String reverseWords(String sentence) {
        String[] words = sentence.split(" ");
        StringBuilder reversedSentence = new StringBuilder();

        for (String word : words) {
            StringBuilder reversedWord = new StringBuilder(word);

            // Reverse the word characters
            for (int i = 0, j = word.length() - 1; i < j; i++, j--) {
                char temp = reversedWord.charAt(i);
                reversedWord.setCharAt(i, reversedWord.charAt(j));
                reversedWord.setCharAt(j, temp);
            }

            reversedSentence.append(reversedWord.toString());
            reversedSentence.append(" ");
        }

        // Trim the last space and return the result
        return reversedSentence.toString().replaceAll("( )+", " ").trim();
    }
